def icon(name):
 return f'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="{ICONS[name]}"/></svg>'
def link(label,target,cl='textlink'):
 return f'<a class="{cl}" href="#{target}">{label}</a>'
def button(label,action,cl='primary'):
 return f'<button class="{cl}" data-action="{action}">{label}</button>'
def row(title,sub,target,ico='file',value=''):
 return f'<a class="row" href="#{target}"><span class="rowicon">{icon(ico)}</span><span class="grow"><strong>{title}</strong><small>{sub}</small></span>{f"<em>{value}</em>" if value else ""}{icon("next")}</a>'
def nav(active):
 return '<nav class="tabs" aria-label="底部主导航">'+''.join(f'<a href="#{target}" class="{"active" if name==active else ""}">{icon(ico)}<span>{name}</span></a>' for name,ico,target in [('日记','book','D01'),('导师','people','mentor-note'),('记忆','memory','M01'),('设置','settings','S01')])+'</nav>'
def header(title,back=None,more=None):
 return f'<header class="appbar">{link(icon("back"),back,"iconbtn") if back else link(icon("folder"),"D02","iconbtn")}<span>{title}</span>{link(icon("more"),more,"iconbtn") if more else "<span class=spacer></span>"}</header>'
def section(title,linktext='',target=''):
 return f'<div class="sectionhead"><h3>{title}</h3>{link(linktext,target) if linktext else ""}</div>'
def chip(text):return f'<span class="chip">{text}</span>'
def notice(text):return f'<div class="notice">{text}</div>'
